CREATE VIRTUAL TABLE ft USING fts3(a, b); WITH RECURSIVE n(ii) AS (VALUES(1) UNION ALL SELECT ii+1 FROM n WHERE ii<31) INSERT INTO ft(a,b) SELECT rtrim(CASE WHEN (ii & 1)<>0 THEN 'one ' ELSE '' END || CASE WHEN (ii & 2)<>0 THEN 'two ' ELSE '' END || CASE WHEN (ii & 4)<>0 THEN 'three ' ELSE '' END || CASE WHEN (ii & 8)<>0 THEN 'four ' ELSE '' END || CASE WHEN (ii & 16)<>0 THEN 'five ' ELSE '' END), rtrim(CASE WHEN (ii & 1)<>0 THEN 'neung ' ELSE '' END || CASE WHEN (ii & 2)<>0 THEN 'song ' ELSE '' END || CASE WHEN (ii & 4)<>0 THEN 'sahm ' ELSE '' END || CASE WHEN (ii & 8)<>0 THEN 'see ' ELSE '' END || CASE WHEN (ii & 16)<>0 THEN 'hah ' ELSE '' END) FROM n ORDER BY ii; DELETE FROM ft WHERE ft MATCH 'one'; DELETE FROM ft WHERE ft MATCH 'three'; DELETE FROM ft WHERE ft MATCH 'five'; INSERT INTO ft VALUES('short alongertoken reallyquitealotlongerimeanit andthistokenisjustsolongthatonemightbeforgivenforimaginingthatitwasmerelyacontrivedexampleandnotarealtoken', 'cynics!');